import{z as s,x as p,o as t,c as A,q as l,j as o,D as e,d as r,s as m,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"曝光宽容度","description":"","frontmatter":{"title":"曝光宽容度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/exposure-latitude.md","filePath":"litho/exposure-latitude.md","lastUpdated":1791063341000}'),d={name:"litho/exposure-latitude.md"};function h(L,a,D,B,u,C){const i=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=l('<h1 id="曝光宽容度" tabindex="-1">曝光宽容度 <a class="header-anchor" href="#曝光宽容度" aria-label="Permalink to &quot;曝光宽容度&quot;">​</a></h1><div class="epigraph"><p>$k_1$ 窗口已经问「这一层还印不印得动」；曝光宽容度把其中一根轴写成剂量还能漂几个百分点。</p><footer>—— 据 Levinson, Principles of Lithography 与 Mack 对 exposure latitude 及工艺窗口的定义整理</footer></div><p><a href="/litho/k1-factor-window">上一课</a>把 \\(k_1\\) 从名义工作点改成可印窗口：RET 买的是面积，不是又一个更小的 \\(\\lambda/\\mathrm{NA}\\)。缺口是把窗口的<strong>剂量轴</strong>单独命名。本课钉曝光宽容度（EL）：最佳焦距附近，CD 仍落在规格内的相对剂量宽度。掩模 CD 误差如何被放大，留给<a href="/litho/meef">下一课</a>。波长台阶仍不是本课的题目。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(k_1\\) 窗口在概念上混着节距、照明、二维图形与「剂量–焦距还剩多少」。产线要在曝光机上拧的是剂量（\\(\\mathrm{mJ/cm^2}\\)）。缺口因此是：在最佳焦面（或指定焦面）上，把合格剂量区间写成相对量</p> \\[\\mathrm{EL}=\\frac{E_\\mathrm{max}-E_\\mathrm{min}}{E_\\mathrm{center}}, \\]<p>其中 \\(E_\\mathrm{max}\\)、\\(E_\\mathrm{min}\\) 是 CD 碰到规格带两端（常用目标 \\(\\pm 10\\%\\)）的剂量。只报「窗口很大」而不报 EL，无法判断剂量控制、均匀性与光源功率抖动还剩多少余量。</p><p><span class="marginnote">数字代入：若规格带是目标 CD 的 \\(\\pm 10\\%\\)，实测 \\(E_\\min=90\\)、\\(E_\\max=110\\ \\mathrm{mJ/cm^2}\\) 都合格，则 \\(\\mathrm{EL}=(110-90)/100=20\\%\\)；若窗口只剩 \\(90\\) 到 \\(98\\)，EL 就只有 \\(8\\%\\)——产线的剂量控制预算必须比它更紧。</span></p><p>EL 是窗口在剂量轴上的切片，不是胶的 \\(\\gamma\\) 的别名。\\(\\gamma\\) 陡可以切锐，但光学 NILS 不够时，EL 仍然瘦。</p><h3 id="el-不是-dof" tabindex="-1">EL 不是 DOF <a class="header-anchor" href="#el-不是-dof" aria-label="Permalink to &quot;EL 不是 DOF&quot;">​</a></h3><p>焦深是 \\(z\\) 轴宽度，EL 是 \\(E\\) 轴相对宽度。两者在 E–D 图上围成面积，可以此消彼长：离轴照明常买 DOF、不一定买 EL。比较不同 RET 必须两根轴都看，不能只把 \\(k_1\\) 压低当成绩。</p><p><span class="marginnote">EL 要声明图形、规格带与焦面。密线、孤立线、孔的 EL 不同；层的剂量必须同时养活重叠窗口里最窄的那一根轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：曝光矩阵在最佳焦附近扫剂量，量 CD，读规格带内的 \\(E\\) 区间，除以中心剂量。模拟：阈值或校准胶模型上对 \\(I(x)\\) 做同样的切。光学预言来自 NILS 课：相对 CD 误差随相对剂量误差涨、随 NILS 降，因而 EL 与 NILS 同向。Mack 把 NILS 当 EL 的空中像代理；硅片 EL 还要扣扩散、计量偏置。</p><p>\\(k_1\\) 降低时，通带边缘调制变弱，NILS 掉，EL 先于「名义分辨率」关门。RET 若只把某一节距的对比抬上去，EL 的成绩单仍是重叠窗口里最差的图形。</p><h3 id="与-k1-窗口的接口" tabindex="-1">与 k₁ 窗口的接口 <a class="header-anchor" href="#与-k1-窗口的接口" aria-label="Permalink to &quot;与 k₁ 窗口的接口&quot;">​</a></h3><p>上一课的成功判据是窗口面积可量产。本课把面积的一条边标成 EL。另一条边是 DOF（Bossung 横切）。后课 MEEF 是第三种误差源：掩模 CD 不稳时，即使 EL 数字好看，晶圆 CD 仍可能出格——那不是剂量轴，不要塞进本课的公式。</p><p><span class="marginnote">剂量单位是 \\(\\mathrm{mJ/cm^2}\\)，EL 是无量纲（常报百分数）。不要把 EL 与焦深纳米加总成一个「越大越好」而不声明规格与图形。</span></p>',18)),(t(),o(n,null,{default:e(()=>[m(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20K1%5B%22k%E2%82%81%20%E5%8F%AF%E5%8D%B0%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20EL%5B%22%E5%89%82%E9%87%8F%E8%BD%B4%EF%BC%9AEL%22%5D%0A%20%20K1%20--%3E%20DOF%5B%22%E7%84%A6%E8%BD%B4%EF%BC%9ADOF%22%5D%0A%20%20NILS%5B%22NILS%22%5D%20--%3E%20EL%0A%20%20EL%20--%3E%20ED%5B%22E%E2%80%93D%20%E9%9D%A2%E7%A7%AF%22%5D%0A%20%20EL%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%8E%A9%E6%A8%A1%E8%AF%AF%E5%B7%AE%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"阈值切在空中像斜坡上。剂量升高，相对阈值下移，两边外扩或内缩（视正负胶与线/空）。斜坡越陡（NILS 越大），同样 \\(\\Delta E/E\\) 引起的 \\(\\Delta\\mathrm{CD}/\\mathrm{CD}\\) 越小，规格带内能容纳的剂量区间越宽。零级偏置抬高 \\(I_\\mathrm{min}\\)，切点落到缓区，EL 崩掉——这与 \\(k_1\\) 靠近单次地板是同一光学事实的剂量读出。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"把空中像的边沿想成滑梯：阈值切在陡滑梯上，剂量涨落只让切点滑一点点；切在缓坡上，同样的涨落切点大幅移动，线宽跟着大幅摆动。NILS 就是滑梯的陡度——EL 宽不宽，先看坡。")],-1)),(t(),o(n,null,{default:e(()=>[m(i,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E8%BE%B9%E6%B2%BF%E6%96%9C%E5%9D%A1%22%5D%20--%3E%20Q%7B%22NILS%20%E5%A4%A7%20(%E5%9D%A1%E9%99%A1)%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20W1%5B%22%E5%90%8C%E6%A0%B7%E5%89%82%E9%87%8F%E6%BC%82%E7%A7%BB%2C%20CD%20%E5%8F%98%E5%8C%96%E5%B0%8F%22%5D%0A%20%20W1%20--%3E%20ELW%5B%22EL%20%E5%AE%BD%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20W2%5B%22%E5%BE%AE%E5%B0%8F%E5%89%82%E9%87%8F%E6%BC%82%E7%A7%BB%2C%20CD%20%E5%87%BA%E6%A0%BC%22%5D%0A%20%20W2%20--%3E%20ELS%5B%22EL%20%E7%AA%84%22%5D%0A%20%20Z0%5B%22%E9%9B%B6%E7%BA%A7%E5%81%8F%E7%BD%AE%E6%8A%AC%E9%AB%98%20I_min%22%5D%20--%3E%20FLAT%5B%22%E5%9D%A1%E5%8F%98%E7%BC%93%22%5D%0A%20%20FLAT%20--%3E%20Q%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>这张图回答的是：NILS 如何决定 EL 宽窄——阈值切点的斜坡越陡，剂量轴上的合格区间越宽；零级偏置把坡压缓，EL 就先于名义分辨率关门。</p><p>扫描机的剂量均匀性、狭缝积分、脉冲能量抖动，全部吃 EL。控制余量必须小于本课定义的窗口，而不是等于它。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到工艺窗口的剂量轴，就是 EL，须附规格与图形。说到压 \\(k_1\\)，默认要检查 EL 是否还活着，而不是只看名义半节距。MEEF 下一课另开误差通道。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>EL 不含套刻、不含缺陷密度、不含刻蚀后偏置——除非量的就是刻蚀后 CD。EUV 随机失效可能在平均 CD 仍合格时先关窗，那是随机课的尾部。本课不编造某代机台「EL 必须大于百分之几」的内部门槛；教科书用 \\(\\pm 10\\%\\) CD 只是常用举例，不是物理常数。</p><p><span class="marginnote">初学者容易拿「平均 CD 还合格」判断窗口安全。EUV 的随机缺孔这类尾部失效，可能在平均 CD 出格之前先把产线判死；EL 是剂量轴上的平均场窗口，尾部统计另有一本账。</span></p><p>波长换档会同时改 NILS 与剂量绝对量，那是波长课；本课在固定 \\(\\lambda\\)、\\(\\mathrm{NA}\\) 下谈相对剂量宽度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EL 是最佳焦附近 CD 合格的相对剂量宽度，是 \\(k_1\\) 窗口的剂量轴。</li><li>它与 DOF 正交；面积才是层窗口。</li><li>光学上 EL 随 NILS 涨，随 \\(k_1\\) 贴近地板而瘦。</li><li>必须声明图形与规格带；\\(\\gamma\\) 不能替代 NILS。</li><li>下一课：掩模 CD 误差的放大不走剂量轴。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',10))])}const f=s(d,[["render",h]]);export{c as __pageData,f as default};
